    .string "(> a b)"
.L15727:
    .string "Greater than."
.L15728:
    .string "<="
.L15729:
    .string "operator"
.L15730:
    .string "(<= a b)"
.L15731:
    .string "Less than or equal."
.L15732:
    .string ">="
